   TimedActionAppeaseDesc$1: "Die Beschwichtigung von Rebellen verringert die <i>Rebellion</i> um $1. Sie ist nur verfügbar, wenn sich das Gebiet derzeit <i>nicht</i> in Rebellion befindet.",
   TimedActionCrackdownDesc$1$2$3: "Das Durchgreifen gegen Rebellen setzt die <i>Rebellion</i> auf $1 zurück, erhöht aber die <i>Unruhe</i> für $3 Jahre um $2. Es ist nur verfügbar, wenn sich das Gebiet derzeit in Rebellion befindet.",
   TimedActionDemandElectionBackingDesc$1: "Die Forderung nach Wahlunterstützung veranlasst sie, uns bei der bevorstehenden Konsulwahl zu unterstützen, wodurch unsere Unterstützung der Provinzen um $1 steigt.",
   TimedActionDemandTileDesc: "Die Forderung eines Gebiets als Großmacht zwingt sie bei Annahme unserer Forderung, das Gebiet an uns abzutreten.",
   TimedActionDemandTributeDesc: "Die Forderung von Tribut als Großmacht gewährt uns bei Annahme unserer Forderung einmalig Gold.",
   TimedActionDenounceDesc$1$2$3: "Das Anprangern einer Provinz senkt ihre Haltung uns gegenüber um $1 und erhöht unser Prestige um $2 ($3, falls sie unser Rivale ist).",
   TimedActionDeterAggressionDesc$1$2: "Die Abschreckung von Aggression verpflichtet uns, dem Verteidiger gegen diese Provinz beizustehen, falls sie eine andere Provinz angreift. Während die Abschreckung wirkt, steigt unser Prestige um $1 ($2, falls sie unser Rivale ist).",
   TimedActionDissolveTreatyDesc: "Das Auflösen eines Vertrags beendet den diplomatischen Vertrag einer Provinz mit einer anderen Provinz. Außerdem hindert es die Provinz daran, neue Verträge zu schließen.",
   TimedActionEvangelizeTileDesc: "Die Missionierung eines nichtchristlichen Gebiets bekehrt es zur Religion unserer Provinz.",
   TimedActionFabricateCasusBelliDesc: "Das Fingieren eines Casus Belli gewährt uns den Casus Belli <i>Diplomatischer Streit</i> gegen sie.",
   TimedActionForceAttackDesc$1$2: "Bei einem gewaltsamen Angriff verlieren wir im Falle einer Abwehr $1 unseres stehenden Heeres statt $2 Kriegswertung.",
   TimedActionFortifyBordersDesc$1: "Die Befestigung unserer Grenzen erhöht die Mannstärke unserer an Kriegszielgebiete angrenzenden Gebiete um $1.",
   TimedActionGuaranteeDefenseDesc$1: "Eine Verteidigungsgarantie verpflichtet uns, ihrem Verteidigungskrieg beizutreten, wenn sie angegriffen werden. Solange die Garantie gilt, steigt ihre Haltung uns gegenüber um $1.",
   TimedActionHireMercenariesDesc: "Die Anwerbung von Söldnern verstärkt unsere Armee sofort bis zur Zieleinberufung.",
   TimedActionInciteUnrestDesc$1: "Das Schüren von Grenzunruhen erhöht die Unruhe ihrer an unsere Provinz angrenzenden Gebiete um $1.",
   TimedActionPlunderWarTileDesc: "Das Plündern eines umkämpften Gebiets verringert die <i>benötigte Kriegswertung</i> und schwächt die Aufwertungen des Gebiets.",
   TimedActionPublicEnemyDesc$1: "Eine Provinz zum <i>Staatsfeind</i> zu erklären, verringert ihr <i>Prestige</i> und ihre <i>Kriegsmacht</i> um $1. Alle anderen Provinzen erhalten gegen sie den Casus Belli <i>Staatsfeind</i>.",
   TimedActionRequestMilitaryAidDesc$1$2: "Das Anfordern von Militärhilfe erhöht unsere Kriegsmacht um $1 und verringert die Kriegsmacht unseres Klientelstaats um $2.",
   TimedActionRevealElectionBackingDesc: "Das Aufdecken der Wahlunterstützung zeigt uns die beiden Kandidaten, denen sie Unterstützung zugesagt haben.",
   TimedActionSetGovernmentFocusDesc: "Das Festlegen des Regierungsschwerpunkts erhöht die monatliche Erzeugung des gewählten Bereichs auf Kosten der beiden anderen Bereiche.",
   TimedActionSubvertGarrisonDesc$1: "Die Unterwanderung der Grenzgarnison verringert die Verteidigung ihrer an unsere Provinz angrenzenden Gebiete um $1.",
   TimedActionSummonGovernorDesc$1$2: "Die Einberufung des Statthalters eines Klientelstaats erhöht unser Prestige um $1 und verringert das Prestige unseres Klientelstaats um $2.",
   TimedActionUpgradeInfrastructureDesc: "Die Aufwertung der Gebietsinfrastruktur kostet Verwaltungspunkte und erhöht die <i>Grundsteuer</i> des Gebiets.",
   TimedActionUpgradePopulationDesc: "Die Aufwertung der Gebietsbevölkerung kostet Militärpunkte und erhöht die <i>Mannstärke</i> des Gebiets.",
   TimedActionUpgradeProductionDesc: "Die Aufwertung der Gebietsproduktion kostet Diplomatiepunkte und erhöht die <i>Produktion</i> des Gebiets.",
