   Year: "Jahr",
   YearOfTheFiveEmperors: "Jahr der fünf Kaiser",
   YearOfTheFiveEmperorsDesc:
      "Kaiser Commodus ist tot, und mit ihm die zerbrechliche Ordnung Roms. Die Provinzen sind gespalten und werden von Gewalt und Zufall beherrscht. Als Statthalter müssen wir diesen Augenblick nutzen – um Rivalen zu unterwerfen, die Ordnung wiederherzustellen und das Reich für Rom zurückzugewinnen.",
   YearOfTheSixEmperors: "Jahr der sechs Kaiser",
   YearOfTheSixEmperorsDesc: "In einem einzigen Jahr steigen und fallen Kaiser wie Blätter im Sturm. Das Reich überlebt – doch nur durch völlige Erschöpfung.",
