   MusterMobileFrontierTroops: "Bewegliche Grenztruppen aufbieten",
   TheRoadsToItalia: "Die Straßen nach Italia",
   TheRoadsToItaliaDesc: "Radagaisus und ein gewaltiges gotisches Heer ziehen durch die Donaulande nach Italia, während kaiserliche Verstärkungen anderswo gebunden sind. Flüchtlinge drängen sich auf unseren Straßen, und jedes Grenzkastell bittet uns um Männer und Getreide.",
   HoldTheRemainingDanubeForts: "Die verbliebenen Donaukastelle halten",
