   StripTheAbandonedPosts: "Die verlassenen Posten räumen",
   TheHunsDemandOurFrontier: "Die Hunnen fordern unsere Grenze",
   TheHunsDemandOurFrontierDesc: "Ravennas Gesandte haben mit den hunnischen Herrschern verhandelt, und hunnische Anführer fordern nun Kastelle, Vorräte und Geiseln von unserer Verwaltung. Kein Entsatzheer wird kommen, doch Pannonia bleibt unserer Herrschaft unterstellt, solange wir nicht nachgeben.",
