   ReinforceTheFrontierTowns: "Die Grenzstädte verstärken",
   RecruitHunnicBorderGuards: "Hunnische Grenzwachen anwerben",
   TheEarthquakeAtSavaria: "Das Erdbeben von Savaria",
   TheEarthquakeAtSavariaDesc: "Ein heftiges Erdbeben, das die Annalisten auf 455 oder 456 datieren, hat Savaria getroffen. Öffentliche Gebäude sind eingestürzt, Familien schlafen im Freien, und die Straßen des westlichen Pannonia sind von Überlebenden verstopft, die Nahrung und Unterkunft suchen.",
   RebuildThePublicBuildings: "Die öffentlichen Gebäude wiederaufbauen",
   HouseSurvivorsOnNearbyEstates: "Überlebende auf nahen Gütern unterbringen",
   SalvageStoneForTheFrontier: "Steine für die Grenze bergen",
   ClaimsOnTheUpperDanube: "Ansprüche an der oberen Donau",
   ClaimsOnTheUpperDanubeDesc:
      "Unsere verstärkten Städte und die volle Schatzkammer erlauben uns, über Pannonias Westgrenze hinauszublicken. Kaufleute und Offiziere meinen, Vindobona und Flavia Solva würden die Straßen an der oberen Donau sichern, wenn wir bereit sind, förmliche Ansprüche zu finanzieren und uns auf einen Krieg mit Noricum vorzubereiten.",
   PressOurNoricanClaims: "Unsere norischen Ansprüche durchsetzen",
   APannonianCoast: "Eine pannonische Küste",
   APannonianCoastDesc: "Drei Mittelmeergebiete an der Küste unterstehen nun unserer Verwaltung. Einst führten Flussstraßen Waren aus Pannonia nach Süden; nun stehen unsere Amtsträger, Gesandten und Soldaten an eigenen Häfen. Wir müssen entscheiden, welcher Regierungszweig diese neue Seegrenze gestalten soll.",
   AdministerTheCoastalCities: "Die Küstenstädte verwalten",
   OpenTheHarborsToEnvoys: "Die Häfen für Gesandte öffnen",
   MusterTheCoastalGarrisons: "Die Küstengarnisonen aufbieten",
   TheNoricanPetition: "Das norische Gesuch",
   TheNoricanPetitionDesc: "Unser Reich ist gewachsen, während Noricum auf eine Handvoll Gebiete geschrumpft ist. Eine dynastische Ehe und ein Verteidigungsabkommen binden unsere Höfe bereits, und norische Gesandte fragen nun, ob daraus dauerhafter Schutz unter Pannonia werden kann.",
   PannoniaAscendant: "Pannonia im Aufstieg",
   PannoniaAscendantDesc:
      "Fünf Siege und zehn neu gesicherte Kerngebiete haben das Ansehen unserer Verwaltung verwandelt. Soldaten, Senatoren und Provinzgemeinden beanspruchen jeweils den Verdienst für Pannonias Aufstieg, und unser Rat muss entscheiden, welche Ordnung aus Eroberung dauerhafte Autorität entstehen lässt.",
