   PannoniaBetweenEastAndWest: "Pannonia zwischen Ost und West",
   PannoniaBetweenEastAndWestDesc: "Noricum und Dalmatia sind fest an unser Reich gebunden, sodass Pannonia die Zugänge zu den Alpen und das adriatische Hinterland beherrscht. Unser Rat sieht nun zwei Wege zu größerer Macht: westwärts nach Raetia und Italia oder ostwärts an der Donau entlang nach Moesia und Dacia.",
